def gutenberg_epub(extra=None):
    """The EPUB's bytes: ``mimetype`` first and stored, as the format asks;
    ``extra`` members added after."""
    import io
    import zipfile

    buf = io.BytesIO()
    with zipfile.ZipFile(buf, 'w') as z:
        z.writestr('mimetype', GUTENBERG_EPUB['mimetype'], compress_type=zipfile.ZIP_STORED)
        for name, text in GUTENBERG_EPUB.items():
            if name != 'mimetype':
                z.writestr(name, text, compress_type=zipfile.ZIP_DEFLATED)
        z.writestr(GUTENBERG_EPUB_COVER, PNG)
        for name, data in (extra or {}).items():
            z.writestr(name, data, compress_type=zipfile.ZIP_DEFLATED)
    return buf.getvalue()
